with original as (select *,case when strpos(content->>'script_text',chr(10))>0 then chr(10) else chr(92)||'n' end as sep from daisy_call_scripts where script_number=40 and version=22 and archived_at is null and deleted_at is null), changed as (update daisy_call_scripts s set content=jsonb_set(o.content,'{script_text}',to_jsonb(replace(o.content->>'script_text','[PrepHub:needs]','[PrepHub:login_clarification]'||o.sep||'Just to make sure I understand you correctly, were you able to log in?'||o.sep||o.sep||'[PrepHub:reply_clarification]'||o.sep||'Just to make sure I understand you correctly, was that a yes or a no?'||o.sep||o.sep||'[PrepHub:needs]'))),version=23,history=o.history||jsonb_build_array(jsonb_build_object('version',o.version,'title',o.title,'category',o.category,'direction',o.direction,'content',o.content,'saved_at',now())),updated_at=now(),finalized_at=now() from original o where s.id=o.id and s.version=22 returning s.id,s.version,s.content) select id,version,content->>'script_text' like '%were you able to log in?%' as login_clarification_saved,content->>'script_text' like '%was that a yes or a no?%' as general_clarification_saved from changed;
